(() => {
 const E=escapeHTML, money=n=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR'}).format(n/100);
 const token=()=>Array.from(crypto.getRandomValues(new Uint8Array(32)),b=>b.toString(16).padStart(2,'0')).join('');
 let event=new URLSearchParams(location.search).get('event')||'',inventory,operatorKey='',passToken='',pending,stream,scanTimer;
 const main=$('workspace');
 const section=(id,html)=>{const el=document.createElement('section');el.id=id;el.className='operations-page';el.hidden=true;el.innerHTML=html;main.querySelector('footer').before(el);};
 section('visitor-page',`<div class="ops-banner"><strong>Demo event booking</strong><span>Sample parking locations and prices. Passes are for this demo only and do not grant access to a real car park. No payment is collected.</span></div><div class="ops-layout"><div><section class="panel ops-box"><h2>Register & reserve parking</h2><div id="visitor-event">Open an event link from your organiser, or create a demo event in Operator desk.</div><form id="visitor-form"><label for="visitor-name">Attendee name or demo alias</label><input id="visitor-name" required maxlength="60" autocomplete="name"><label for="visitor-lot">Parking zone</label><select id="visitor-lot"><option value="">No parking · attendee registration only</option></select><label class="ops-check"><input type="checkbox" id="visitor-accessible"> I need an accessible parking space</label><p id="visitor-price">Registration is free. One attendee and at most one car per pass.</p><button class="button lime" id="reserve-pass" disabled>Register & create pass</button><p class="form-note">Your name is stored with your pass. Keep its code private: anyone with it can view the pass. Download your pass to use it on another device.</p></form></section><section class="panel ops-box"><div class="section-heading"><h2>Parking availability</h2><button type="button" class="button light" id="visitor-refresh">Refresh</button></div><p class="data-note">Availability comes from reservations and operator scans, not sensors. Refresh before booking.</p><div id="visitor-lots" class="ops-lots"></div></section></div><div><section class="panel ops-box"><h2>Your visitor pass</h2><form id="lookup-pass"><label for="lookup-code">Pass code or pass link</label><input id="lookup-code" required autocomplete="off"><button class="button light">Retrieve pass</button></form><div id="visitor-pass"><p>Your QR pass will appear here after registration.</p></div></section></div></div><p id="visitor-status" class="ops-status" role="status"></p>`);
 section('operator-page',`<div class="ops-banner"><strong>Operator desk</strong><span>Each demo event has its own inventory and private operator key. Save the key to reopen your controls on another device.</span></div><div class="ops-layout"><section class="panel ops-box"><h2>Create a demo event</h2><form id="create-event"><label for="ops-event-name">Event name</label><input id="ops-event-name" required maxlength="80" value="Sector 17 Evening Festival"><label for="ops-event-date">Event date</label><input id="ops-event-date" type="date" required value="${E($('date').value)}"><label for="ops-event-capacity">Attendee capacity</label><input id="ops-event-capacity" type="number" min="1" max="2000" value="500" required><button class="button lime">Create demo event</button></form><p class="data-note">Creates three sample zones. Adjust their capacities and prices below. Maximum 2,000 attendee registrations per demo.</p><button id="use-studio-event" class="button light" type="button">Use Studio event details</button><div id="created-event"></div></section><section class="panel ops-box"><h2>Open operator controls</h2><form id="operator-login"><label for="operator-event">Event ID or visitor link</label><input id="operator-event" required autocomplete="off"><label for="operator-key">Operator key</label><input id="operator-key" type="password" required autocomplete="off"><button class="button dark">Unlock controls</button></form><p class="data-note">The operator key permits price changes and check-in. It stays in this tab’s session. Share it only with trusted event staff.</p><button class="button light" type="button" id="operator-lock" hidden>Lock controls</button></section></div><div id="operator-controls" hidden><section class="panel ops-box"><div class="section-heading"><h2>Inventory & prices</h2><button class="button light" id="operator-refresh">Refresh counts</button></div><div id="operator-summary"></div><div id="operator-lots" class="ops-lots"></div></section><section class="panel ops-box"><h2>Attendee check-in & parking gates</h2><p>Choose the gate action, scan or paste a pass, then record it. Repeated scans cannot check in the same pass twice.</p><form id="scan-pass"><label for="scan-action">Gate action</label><select id="scan-action"><option value="attendee">Attendee check-in</option><option value="entry">Parking entry</option><option value="exit">Parking exit</option></select><label for="scan-code">Pass code or QR contents</label><input id="scan-code" required autocomplete="off"><button class="button lime">Record scan</button></form><div class="planning-buttons"><button type="button" class="button light" id="camera-start">Scan with camera</button><button type="button" class="button light" id="camera-stop" hidden>Stop camera</button><label class="button light">Read QR image<input id="qr-image" type="file" accept="image/*" hidden></label></div><video id="scan-video" playsinline muted hidden></video><p class="data-note">Camera requires your permission. You can always paste the code or select a QR image. Exiting releases a parking space; the same pass cannot re-enter.</p></section></div><p id="operator-status" class="ops-status" role="status"></p>`);
 const status=(scope,text,error=false)=>{const el=$(scope+'-status');el.textContent=text;el.classList.toggle('error',error);};
 async function api(path,body,admin=false){const url='/api/operations/'+path+(body?'':'?event='+encodeURIComponent(event));const r=await fetch(url,{method:body?'POST':'GET',headers:{...(body?{'Content-Type':'application/json'}:{}),...(admin?{Authorization:'Bearer '+operatorKey}:{})},...(body?{body:JSON.stringify({event,...body})}:{})});let data;try{data=await r.json();}catch{throw new Error('Server unavailable. Keep your code and try again.');}if(!r.ok)throw new Error(data.error||'Request failed.');return data;}
 async function action(scope,button,fn){button.disabled=true;status(scope,'Working…');try{await fn();}catch(e){status(scope,e.message,true);}finally{button.disabled=button.id==='reserve-pass'&&(!inventory||inventory.stats.registered>=inventory.event.capacity);}}
 function eventFrom(value){try{return new URL(value).searchParams.get('event')||value.trim();}catch{return value.trim();}}
 function codeFrom(value){try{const url=new URL(value);if(url.origin!==location.origin)throw new Error('Use a pass from this website.');const parts=new URLSearchParams(url.hash.slice(1));const ev=url.searchParams.get('event');if(ev&&ev!==event)throw new Error('This pass belongs to a different event.');return parts.get('pass')||value.trim();}catch(e){if(e.message.startsWith('Use a pass')||e.message.startsWith('This pass'))throw e;return value.trim();}}
 function setEvent(id){event=id;const url=new URL(location.href);url.searchParams.set('event',id);history.replaceState({},'',url);$('operator-event').value=id;document.querySelectorAll('[data-page]').forEach(a=>{const next=new URL(a.href,location.href);next.searchParams.set('event',id);a.href=next.pathname+next.search;});}
 function publicLink(){return location.origin+'/visitor?event='+encodeURIComponent(event);}
 function rememberOperator(){try{sessionStorage.setItem('urbanpulse-operator',JSON.stringify({event,key:operatorKey}));}catch{}}
 async function refresh(){if(!event)return;inventory=await api('inventory');const v=inventory;$('visitor-event').innerHTML=`<h3>${E(v.event.name)}</h3><p>${E(v.event.date)} · ${v.stats.registered} / ${v.event.capacity} registered</p>`;const selected=$('visitor-lot').value;$('visitor-lot').innerHTML='<option value="">No parking · attendee registration only</option>'+v.lots.map(l=>`<option value="${E(l.id)}" ${!l.open||l.reserved>=l.capacity?'disabled':''}>${E(l.name)} · ${money(l.price)} · ${Math.max(0,l.capacity-l.reserved)} available${!l.open?' · closed':''}</option>`).join('');if(v.lots.some(l=>l.id===selected&&l.open&&l.reserved<l.capacity))$('visitor-lot').value=selected;$('reserve-pass').disabled=v.stats.registered>=v.event.capacity;
 $('visitor-lots').innerHTML=v.lots.map(l=>`<article class="ops-lot"><h3>${E(l.name)}</h3><strong>${l.open?Math.max(0,l.capacity-l.reserved)+' available':'Closed to new bookings'}</strong><p>${money(l.price)} per event · ${l.accessible?'Accessible zone':'Standard zone'}</p><p>${l.reserved} reserved or inside / ${l.capacity} spaces · ${l.occupied} checked in</p><small>Operator update: ${E(new Date(l.updated).toLocaleString())}</small></article>`).join('');$('operator-summary').innerHTML=`<p><strong>${E(v.event.name)}</strong> · ${v.stats.registered} registered · ${v.stats.checked} attendees checked in</p><p>Visitor link: <a href="${E(publicLink())}">${E(publicLink())}</a></p><p class="data-note">Sample inventory. Prices apply to new bookings; existing passes keep their quoted price.</p>`;
 if(operatorKey){$('operator-lots').innerHTML=v.lots.map(l=>`<form class="ops-lot" data-lot="${E(l.id)}"><h3>${E(l.name)}</h3><p>${l.reserved} committed · ${l.occupied} inside</p><label>Capacity<input name="capacity" type="number" min="${l.reserved}" max="2000" required value="${l.capacity}"></label><label>Price per event (₹)<input name="price" type="number" min="0" max="10000" step="0.01" required value="${l.price/100}"></label><label class="ops-check"><input name="open" type="checkbox" ${l.open?'checked':''}> Accept new bookings</label><button class="button dark">Save zone</button></form>`).join('');}
 $('visitor-price').textContent=$('visitor-lot').value?`Parking quote: ${money(v.lots.find(l=>l.id===$('visitor-lot').value).price)} per event. Demo only; no payment collected.`:'Free attendee registration. One attendee per pass.';}
 $('visitor-lot').onchange=()=>{const lot=inventory?.lots.find(l=>l.id===$('visitor-lot').value);$('visitor-price').textContent=lot?`Parking quote: ${money(lot.price)} per event. Demo only; no payment collected.`:'Free attendee registration. One attendee per pass.';pending=null;};
 $('visitor-form').addEventListener('input',()=>{pending=null;});
 function svgFor(value){const qr=qrcode(0,'M');qr.addData(value);qr.make();return qr.createSvgTag({cellSize:4,margin:16,scalable:true});}
 let downloadHTML='';
 async function displayPass(code){const {pass}=await api('pass',{token:code});passToken=code;const link=publicLink()+'#pass='+code;const svg=svgFor(link);const content=`<div class="visitor-ticket"><p class="eyebrow">URBANPULSE · DEMO PASS</p><h3>${E(pass.event_name)}</h3><p>${E(pass.name)} · ${E(pass.event_date)}</p><div class="qr-pass">${svg}</div><strong>${E(pass.lot_name||'Attendee registration only')}</strong><p>${money(pass.price)} quoted · not paid / no charge collected</p><p>Status: ${E(pass.status)} · Attendee: ${pass.checked?'checked in':'not checked in'} · Parking: ${E(pass.parking)}</p><p class="data-note">No real parking entitlement. One parking entry per pass.</p><label>Private pass code<textarea readonly>${E(code)}</textarea></label></div>`;$('visitor-pass').innerHTML=content+'<div class="planning-buttons"><button id="download-pass" class="button lime">Download QR pass</button><button id="refresh-pass" class="button light">Refresh status</button><button id="cancel-pass" class="button light" '+(pass.status!=='active'||pass.checked||!['reserved','none'].includes(pass.parking)?'disabled':'')+'>Cancel reservation</button></div>';
 downloadHTML='<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>UrbanPulse visitor pass</title><style>body{font:16px system-ui;max-width:460px;margin:30px auto;padding:20px;color:#182a2a}.qr-pass{max-width:250px}textarea{width:100%;height:70px}button{display:none}</style>'+content+`<p><a href="${E(link)}">Open pass status</a></p>`;
 $('download-pass').onclick=()=>{const a=document.createElement('a');const url=URL.createObjectURL(new Blob([downloadHTML],{type:'text/html'}));a.href=url;a.download='UrbanPulse-visitor-pass.html';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};$('refresh-pass').onclick=e=>action('visitor',e.target,async()=>{await displayPass(passToken);status('visitor','Pass status refreshed.');});$('cancel-pass').onclick=e=>action('visitor',e.target,async()=>{await api('cancel',{token:passToken});await displayPass(passToken);await refresh();status('visitor','Reservation cancelled; capacity released.');});
 $('lookup-code').value=code;try{sessionStorage.setItem('urbanpulse-visitor-pass',JSON.stringify({event,code}));}catch{}
 }
 $('visitor-form').onsubmit=e=>{e.preventDefault();action('visitor',$('reserve-pass'),async()=>{if(!event)throw new Error('Open an event link first.');pending||=token();$('lookup-code').value=pending;try{sessionStorage.setItem('urbanpulse-visitor-pass',JSON.stringify({event,code:pending}));}catch{}const lot=inventory?.lots.find(l=>l.id===$('visitor-lot').value);await api('reserve',{name:$('visitor-name').value,lot:lot?.id||null,price:lot?.price||0,accessible:$('visitor-accessible').checked,token:pending});await displayPass(pending);await refresh();status('visitor','Registration confirmed. Download your QR pass.');});};
 $('lookup-pass').onsubmit=e=>{e.preventDefault();action('visitor',e.submitter,async()=>{await displayPass(codeFrom($('lookup-code').value));status('visitor','Pass retrieved.');});};
 $('visitor-refresh').onclick=e=>action('visitor',e.target,async()=>{await refresh();status('visitor','Availability refreshed at '+new Date().toLocaleTimeString());});
 let createAttempt;
 $('create-event').addEventListener('input',()=>createAttempt=null);
 $('create-event').onsubmit=e=>{e.preventDefault();action('operator',e.submitter,async()=>{createAttempt||={id:crypto.randomUUID(),operatorKey:token()};await api('events',{...createAttempt,name:$('ops-event-name').value,date:$('ops-event-date').value,capacity:+$('ops-event-capacity').value});setEvent(createAttempt.id);operatorKey=createAttempt.operatorKey;rememberOperator();$('operator-key').value=operatorKey;$('created-event').innerHTML=`<p><strong>Save your operator key now.</strong> It cannot be recovered if you lose it.</p><label>Private operator key<textarea readonly>${E(operatorKey)}</textarea></label><p><a href="${E(publicLink())}">Open visitor booking page</a></p>`;createAttempt=null;await unlock();status('operator','Demo event created. Save your key and share the visitor link.');});};
 $('use-studio-event').onclick=()=>{$('ops-event-name').value=$('event-name').value;$('ops-event-date').value=$('date').value;createAttempt=null;};
 async function unlock(){await api('operator',null,true);$('operator-controls').hidden=false;$('operator-lock').hidden=false;rememberOperator();await refresh();}
 $('operator-login').onsubmit=e=>{e.preventDefault();action('operator',e.submitter,async()=>{setEvent(eventFrom($('operator-event').value));operatorKey=$('operator-key').value.trim();try{await unlock();status('operator','Operator controls unlocked.');}catch(err){operatorKey='';$('operator-controls').hidden=true;throw err;}});};
 $('operator-lock').onclick=()=>{operatorKey='';$('operator-key').value='';$('operator-controls').hidden=true;$('operator-lock').hidden=true;stopCamera();try{sessionStorage.removeItem('urbanpulse-operator');}catch{}status('operator','Controls locked.');};
 $('operator-refresh').onclick=e=>action('operator',e.target,async()=>{await refresh();status('operator','Counts refreshed.');});
 $('operator-lots').onsubmit=e=>{e.preventDefault();const form=e.target;action('operator',e.submitter,async()=>{await api('lot',{lot:form.dataset.lot,capacity:+form.elements.capacity.value,price:Math.round(+form.elements.price.value*100),open:form.elements.open.checked},true);await refresh();status('operator','Inventory updated. Existing pass prices are unchanged.');});};
 $('scan-pass').onsubmit=e=>{e.preventDefault();action('operator',e.submitter,async()=>{const data=await api('checkin',{token:codeFrom($('scan-code').value),action:$('scan-action').value},true);await refresh();status('operator',data.message);});};
 function stopCamera(){clearTimeout(scanTimer);stream?.getTracks().forEach(t=>t.stop());stream=null;$('scan-video').srcObject=null;$('scan-video').hidden=true;$('camera-stop').hidden=true;}
 function decoded(data){$('scan-code').value=data;stopCamera();status('operator','QR read. Check the gate action, then press Record scan.');}
 const canvas=document.createElement('canvas'),ctx=canvas.getContext('2d',{willReadFrequently:true});
 function readQR(source,width,height){const scale=Math.min(1,1000/Math.max(width,height));canvas.width=Math.round(width*scale);canvas.height=Math.round(height*scale);ctx.drawImage(source,0,0,canvas.width,canvas.height);const pixels=ctx.getImageData(0,0,canvas.width,canvas.height);return jsQR(pixels.data,canvas.width,canvas.height)?.data;}
 $('camera-start').onclick=e=>action('operator',e.target,async()=>{stopCamera();if(!navigator.mediaDevices?.getUserMedia)throw new Error('Camera unavailable. Paste a code or choose a QR image.');stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'}});const video=$('scan-video');video.srcObject=stream;video.hidden=false;$('camera-stop').hidden=false;await video.play();status('operator','Point the camera at a visitor QR pass.');const scan=()=>{if(!stream)return;try{if(video.videoWidth){const result=readQR(video,video.videoWidth,video.videoHeight);if(result){decoded(result);return;}}}catch{}scanTimer=setTimeout(scan,300);};scan();});
 $('camera-stop').onclick=stopCamera;window.addEventListener('pagehide',stopCamera);document.addEventListener('urbanpulse:page',e=>{if(e.detail!=='operator')stopCamera();});
 $('qr-image').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>10000000)throw new Error('Choose an image smaller than 10 MB.');const bitmap=await createImageBitmap(file);const code=readQR(bitmap,bitmap.width,bitmap.height);bitmap.close();if(!code)throw new Error('QR not found. Try a clearer image or paste the pass code.');decoded(code);}catch(err){status('operator',err.message,true);}finally{e.target.value='';}};
 try{const saved=JSON.parse(sessionStorage.getItem('urbanpulse-operator'));if(saved?.event&&(!event||event===saved.event)){setEvent(saved.event);operatorKey=saved.key;$('operator-key').value=operatorKey;unlock().catch(e=>status('operator',e.message,true));}}catch{}
 if(event){$('operator-event').value=event;refresh().catch(e=>status('visitor',e.message,true));}
 const incoming=new URLSearchParams(location.hash.slice(1)).get('pass');
 try{const saved=JSON.parse(sessionStorage.getItem('urbanpulse-visitor-pass'));const code=incoming||(saved?.event===event?saved.code:null);if(code&&event)displayPass(code).catch(e=>status('visitor',e.message,true));}catch{}
})();
